 // Inverted index over the catalog.
 //
 // The index is built once at module load. A request only touches the postings
 // for the tokens it actually asked for, so search cost scales with the number
 // of matches rather than the size of the catalog.

 import { CATALOG } from "./catalog.mjs";
 import { matchPositions } from "./search-match.mjs";

 /** Lowercase, strip punctuation, drop one-character noise tokens. */
 export function tokenize(text) {
   return text
     .toLowerCase()
     .split(/[^a-z0-9]+/)
     .filter((token) => token.length > 1);
 }

 function buildIndex() {
   const postings = new Map();
   CATALOG.forEach((product, position) => {
     const tokens = tokenize(`${product.name} ${product.color} ${product.category}`);
     for (const token of tokens) {
       let bucket = postings.get(token);
       if (!bucket) {
         bucket = [];
         postings.set(token, bucket);
       }
       // Tokens repeat within a single product name; only index it once.
       if (bucket[bucket.length - 1] !== position) bucket.push(position);
     }
   });
   return postings;
 }

 const POSTINGS = buildIndex();

 /** Category counts across the whole match set, highest count first. */
 function countCategories(products) {
   const counts = new Map();
   for (const product of products) {
     counts.set(product.category, (counts.get(product.category) ?? 0) + 1);
   }
   return [...counts.entries()]
     .map(([category, count]) => ({ category, count }))
     .sort((a, b) => b.count - a.count);
 }

 /**
  * Products matching every token in `query`, most popular first, along with
  * category facet counts computed over the full match set (not just the page).
  * Returns at most `limit` products.
  */
 export function searchProducts(query, limit = 20) {
   const tokens = tokenize(query ?? "");
-  const matches = matchPositions(POSTINGS, tokens);
+  const matches = matchPositions(CATALOG, tokens);
   if (matches.length === 0) return { results: [], facets: [] };

   const products = matches
     .map((position) => CATALOG[position])
     .sort((a, b) => b.popularity - a.popularity);

   return { results: products.slice(0, limit), facets: countCategories(products) };
 }
