 // Match resolution for search: given the query tokens, decide which catalog
 // positions are hits. Ranking, faceting, and paging live in search-index.mjs.

+const FUZZY_MAX_DISTANCE = 2;
+
+function normalize(text) {
+  return text.toLowerCase().replace(/[^a-z0-9 ]+/g, " ");
+}
+
+/** Levenshtein distance, so "bottel" still finds "bottle". */
+function editDistance(a, b) {
+  if (a === b) return 0;
+  let previous = Array.from({ length: b.length + 1 }, (_, i) => i);
+  let current = new Array(b.length + 1);
+  for (let i = 1; i <= a.length; i += 1) {
+    current[0] = i;
+    for (let j = 1; j <= b.length; j += 1) {
+      const substitution = previous[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1);
+      current[j] = Math.min(current[j - 1] + 1, previous[j] + 1, substitution);
+    }
+    [previous, current] = [current, previous];
+  }
+  return previous[b.length];
+}
+
 /**
- * Catalog positions matching every token, via postings-list intersection.
- * Returns an empty array when any token has no postings.
+ * Catalog positions matching every token. A token matches a product when it
+ * appears anywhere in the product's searchable text, or when it is within
+ * FUZZY_MAX_DISTANCE edits of one of that product's words.
  */
-export function matchPositions(postings, tokens) {
+export function matchPositions(catalog, tokens) {
   if (tokens.length === 0) return [];

-  // Intersect smallest-first so the working set shrinks immediately.
-  const buckets = tokens.map((token) => postings.get(token) ?? []);
-  if (buckets.some((bucket) => bucket.length === 0)) return [];
-  buckets.sort((a, b) => a.length - b.length);
+  const matches = [];
+  for (let position = 0; position < catalog.length; position += 1) {
+    const product = catalog[position];
+    const haystack = normalize(`${product.name} ${product.color} ${product.category}`);
+    const words = haystack.split(" ").filter(Boolean);

-  let matches = buckets[0];
-  for (let i = 1; i < buckets.length; i += 1) {
-    const next = new Set(buckets[i]);
-    matches = matches.filter((position) => next.has(position));
-    if (matches.length === 0) return [];
+    const matchesEveryToken = tokens.every(
+      (token) =>
+        haystack.includes(token) ||
+        words.some((word) => editDistance(word, token) <= FUZZY_MAX_DISTANCE),
+    );
+    if (matchesEveryToken) matches.push(position);
   }
   return matches;
 }
"}

